 with (K/'REPAIR_NOTE.md').open('x',encoding='utf8') as f:f.write(note)
 print(json.dumps(dict(passed=True,total_distinct_filesystem_snapshot_increase_bytes=summary['total_distinct_filesystem_snapshot_increase_bytes'],snapshot_increases=summary['physical_filesystem_snapshot_increases'])))
